import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"서비스 상태","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/service-status.md","filePath":"ko-KR/user-guide/settings/service-status.md","lastUpdated":1787586465000}'),a={name:"ko-KR/user-guide/settings/service-status.md"};function i(n,t,l,g,d,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="서비스-상태" tabindex="-1">서비스 상태 <a class="header-anchor" href="#서비스-상태" aria-label="Permalink to &quot;서비스 상태&quot;">​</a></h1><p>서비스 상태 페이지에서는 Lertaro의 백그라운드 인덱싱 서비스의 동작 상태를 모니터링하고 Service, App, Hook 세 프로세스의 실시간 통합 로그를 확인할 수 있습니다. 설정 경로는 <strong>설정 → 서비스 상태</strong>입니다.</p><h2 id="_1-서비스-상태-및-제어" tabindex="-1">1. 서비스 상태 및 제어 <a class="header-anchor" href="#_1-서비스-상태-및-제어" aria-label="Permalink to &quot;1. 서비스 상태 및 제어&quot;">​</a></h2><p>상단 상태 카드에서는 관리자 권한 백그라운드 서비스의 상태를 실시간으로 확인합니다.</p><ul><li><strong>상태 표시</strong>: <ul><li><strong>준비 완료 (Ready)</strong>: 서비스가 정상 작동 중이며 현재 인덱싱된 파일 및 폴더의 총 개수를 표시.</li><li><strong>인덱싱 중 (Indexing)</strong>: 초기 인덱스 구축 또는 증분 스캔 진행 중(스피너 표시).</li><li><strong>설치 중 (Installing)</strong>: Windows 서비스 등록 및 구동 처리 중.</li><li><strong>오류 (Error)</strong>: 서비스가 중지되었거나 비정상 종료된 상태(경고 마크 및 오류 설명 표시).</li></ul></li><li><strong>자가 치유 및 설치 버튼</strong>: 서비스가 미설치 상태이거나 오류가 발생했을 때만 <strong>서비스 설치 및 시작</strong> 버튼이 나타납니다. 정상 작동 중에는 실수로 인한 중단을 방지하기 위해 백그라운드에서 항상 상주합니다.</li></ul><h2 id="_2-3대-프로세스-실시간-로그-뷰어" tabindex="-1">2. 3대 프로세스 실시간 로그 뷰어 <a class="header-anchor" href="#_2-3대-프로세스-실시간-로그-뷰어" aria-label="Permalink to &quot;2. 3대 프로세스 실시간 로그 뷰어&quot;">​</a></h2><p>하단 로그 뷰어는 Lertaro를 구성하는 세 개의 프로세스에 대응하는 독립된 탭으로 구성됩니다.</p><ul><li><strong>App 탭</strong>: 전면 WPF UI, 검색 인터랙션, 단축키 처리, 창 렌더링 로그.</li><li><strong>Hook 탭</strong>: 저수준 전역 키보드 후크 프로세스(<code>Lertaro.Hook.exe</code>)의 키 감지 및 격리 상태 로그.</li><li><strong>Service 탭</strong>: 관리자 권한 백그라운드 서비스(<code>Lertaro.Service.exe</code>)의 USN 저널 파싱, 디스크 스캔, 메모리 트리 구축 및 IPC 통신 로그.</li></ul><h3 id="필터링-및-로그-초기화" tabindex="-1">필터링 및 로그 초기화 <a class="header-anchor" href="#필터링-및-로그-초기화" aria-label="Permalink to &quot;필터링 및 로그 초기화&quot;">​</a></h3><ul><li><strong>로그 레벨 필터</strong>: &quot;전체 / 오류 / 경고 / 정보 / 디버그&quot;를 선택할 수 있으며 심각도에 따라 색상 강조 표시.</li><li><strong>실시간 검색 필터</strong>: 검색어를 입력하여 현재 로그 내용을 즉시 필터링.</li><li><strong>안전한 로그 초기화</strong>: <strong>로그 지우기</strong>를 클릭하여 현재 탭의 로그를 초기화합니다. Service 탭 로그는 IPC를 통해 안전하게 비워집니다.</li></ul>',10)])])}const h=e(a,[["render",i]]);export{_ as __pageData,h as default};
